def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    from heapq import heappush, heappop

    m = len(ops)
    size = 1
    while size < m:
        size <<= 1

    tree = [0] * (2 * size)
    events = []

    for i, op in enumerate(ops):
        if op[0] == 1:
            events.append((op[1], i, op[3]))
            events.append((op[2] + 1, i, 0))
        else:
            events.append((op[1], i, -1))
            events.append((op[2] + 1, i, -2))

    events.sort()
    erases = []
    counts = {}
    k = 0

    while k < len(events):
        position = events[k][0]

        while k < len(events) and events[k][0] == position:
            _, i, value = events[k]
            if value >= 0:
                p = size + i
                tree[p] = value
                p >>= 1
                while p:
                    new_value = max(tree[p << 1], tree[p << 1 | 1])
                    if tree[p] == new_value:
                        break
                    tree[p] = new_value
                    p >>= 1
            elif value == -1:
                heappush(erases, (-i, ops[i][2] + 1))
            k += 1

        while erases and erases[0][1] <= position:
            heappop(erases)

        if k == len(events):
            break

        next_position = events[k][0]
        if erases:
            left = size - erases[0][0] + 1
            right = size + m
            colour = 0
            while left < right:
                if left & 1:
                    colour = max(colour, tree[left])
                    left += 1
                if right & 1:
                    right -= 1
                    colour = max(colour, tree[right])
                left >>= 1
                right >>= 1
        else:
            colour = tree[1]

        if colour:
            counts[colour] = counts.get(colour, 0) + next_position - position

    return [[colour, counts[colour]] for colour in sorted(counts)]
